import{_ as o,a0 as i,w as p,s as b,ao as l,I as a,x as t,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const W=JSON.parse('{"title":"KeeWeb：一個開源且跨平台的密碼管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"KeeWeb：一個開源且跨平台的密碼管理工具 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KeeWeb：一個開源且跨平台的密碼管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KeeWeb：一個開源且跨平台的密碼管理工具 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager","title":"KeeWeb：一個開源且跨平台的密碼管理工具","tag":"201811","desc":""},"relativePath":"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager.md","filePath":"[post].md"}'),d={name:"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager.md"};function u(w,e,h,m,g,f){const s=i("Link");return p(),b("div",null,[e[29]||(e[29]=l('<h1 id="keeweb-一個開源且跨平台的密碼管理工具" tabindex="-1">KeeWeb：一個開源且跨平台的密碼管理工具 <a class="header-anchor" href="#keeweb-一個開源且跨平台的密碼管理工具" aria-label="Permalink to “KeeWeb：一個開源且跨平台的密碼管理工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/keeweb-720x340.png" alt=""></p><p>如果你長時間使用互聯網，那很可能在很多網站上都有很多帳户。所有這些帳户都必須有密碼，而且必須記住所有的密碼，或者把它們寫下來。在紙上寫下密碼可能不安全，如果有多個密碼，記住它們實際上是不可能的。這就是密碼管理工具在過去幾年中大受歡迎的原因。密碼管理工具就像一箇中央存儲庫，你可以在其中存儲所有帳户的所有密碼，併為它設置一個主密碼。使用這種方法，你唯一需要記住的只有主密碼。</p><p><strong>KeePass</strong> 就是一個這樣的開源密碼管理工具，它有一個官方客户端，但功能非常簡單。也有許多 PC 端和手機端的其他密碼管理工具，並且與 KeePass 存儲加密密碼的文件格式兼容。其中一個就是 <strong>KeeWeb</strong>。</p><p>KeeWeb 是一個開源、跨平台的密碼管理工具，具有云同步，鍵盤快捷鍵和插件等功能。KeeWeb使用 Electron 框架，這意味着它可以在 Windows、Linux 和 Mac OS 上運行。</p><h3 id="keeweb-的使用" tabindex="-1">KeeWeb 的使用 <a class="header-anchor" href="#keeweb-的使用" aria-label="Permalink to “KeeWeb 的使用”">​</a></h3><p>有兩種方式可以使用 KeeWeb。第一種無需安裝，直接在網頁上使用，第二中就是在本地系統中安裝 KeeWeb 客户端。</p><h4 id="在網頁上使用-keeweb" tabindex="-1">在網頁上使用 KeeWeb <a class="header-anchor" href="#在網頁上使用-keeweb" aria-label="Permalink to “在網頁上使用 KeeWeb”">​</a></h4>',8)),a("p",null,[e[1]||(e[1]=t("如果不想在系統中安裝應用，可以去 ",-1)),n(s,{href:"https://app.keeweb.info/"},{default:r(()=>[...e[0]||(e[0]=[t("https://app.keeweb.info/",-1)])]),_:1}),e[2]||(e[2]=t(" 使用KeeWeb。",-1))]),e[30]||(e[30]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-webapp.png",alt:""})],-1)),e[31]||(e[31]=a("p",null,"網頁端具有桌面客户端的所有功能，當然也需要聯網才能進行使用。",-1)),e[32]||(e[32]=a("h4",{id:"在計算機中安裝-keeweb",tabindex:"-1"},[t("在計算機中安裝 KeeWeb "),a("a",{class:"header-anchor",href:"#在計算機中安裝-keeweb","aria-label":"Permalink to “在計算機中安裝 KeeWeb”"},"​")],-1)),e[33]||(e[33]=a("p",null,"如果喜歡客户端的舒適性和離線可用性，也可以將其安裝在系統中。",-1)),a("p",null,[e[4]||(e[4]=t("如果使用 Ubuntu/Debian，你可以去 ",-1)),n(s,{href:"https://github.com/keeweb/keeweb/releases/latest"},{default:r(()=>[...e[3]||(e[3]=[t("發佈頁",-1)])]),_:1}),e[5]||(e[5]=t(" 下載 KeeWeb 最新的 .deb 文件，然後通過下面的命令進行安裝：",-1))]),e[34]||(e[34]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i KeeWeb-1.6.3.linux.x64.deb</span></span></code></pre></div>',1)),a("p",null,[e[8]||(e[8]=t("如果用的是 Arch，在 ",-1)),n(s,{href:"https://aur.archlinux.org/packages/keeweb/"},{default:r(()=>[...e[6]||(e[6]=[t("AUR",-1)])]),_:1}),e[9]||(e[9]=t(" 上也有 KeeWeb，可以使用任何 AUR 助手進行安裝，例如 ",-1)),n(s,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:r(()=>[...e[7]||(e[7]=[t("Yay",-1)])]),_:1}),e[10]||(e[10]=t("：",-1))]),e[35]||(e[35]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S keeweb</span></span></code></pre></div><p>安裝後，從菜單中或應用程序啓動器啓動 KeeWeb。默認界面如下：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-desktop-client.png" alt=""></p><h3 id="總體佈局" tabindex="-1">總體佈局 <a class="header-anchor" href="#總體佈局" aria-label="Permalink to “總體佈局”">​</a></h3><p>KeeWeb 界面主要顯示所有密碼的列表，在左側展示所有標籤。單擊標籤將對密碼進行篩選，只顯示帶有那個標籤的密碼。在右側，顯示所選帳户的所有字段。你可以設置用户名、密碼、網址，或者添加自定義的備註。你甚至可以創建自己的字段並將其標記為安全字段，這在存儲信用卡信息等內容時非常有用。你只需單擊即可複製密碼。 KeeWeb 還顯示賬户的創建和修改日期。已刪除的密碼會保留在回收站中，可以在其中還原或永久刪除。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-general-layout.png" alt=""></p><h3 id="keeweb-功能" tabindex="-1">KeeWeb 功能 <a class="header-anchor" href="#keeweb-功能" aria-label="Permalink to “KeeWeb 功能”">​</a></h3><h4 id="雲同步" tabindex="-1">雲同步 <a class="header-anchor" href="#雲同步" aria-label="Permalink to “雲同步”">​</a></h4><p>KeeWeb 的主要功能之一是支持各種遠程位置和雲服務。除了加載本地文件，你可以從以下位置打開文件：</p><ol><li>WebDAV Servers</li><li>Google Drive</li><li>Dropbox</li><li>OneDrive</li></ol><p>這意味着如果你使用多台計算機，就可以在它們之間同步密碼文件，因此不必擔心某台設備無法訪問所有密碼。</p><h4 id="密碼生成器" tabindex="-1">密碼生成器 <a class="header-anchor" href="#密碼生成器" aria-label="Permalink to “密碼生成器”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-password-generator.png" alt=""></p><p>除了對密碼進行加密之外，為每個帳户創建新的強密碼也很重要。這意味着，如果你的某個帳户遭到入侵，攻擊者將無法使用相同的密碼進入其他帳户。</p><p>為此，KeeWeb 有一個內置密碼生成器，可以生成特定長度、包含指定字符的自定義密碼。</p><h4 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to “插件”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-plugins.png" alt=""></p>',17)),a("p",null,[e[12]||(e[12]=t("你可以使用插件擴展 KeeWeb 的功能。其中一些插件用於更改界面語言，而其他插件則添加新功能，例如訪問 ",-1)),n(s,{href:"https://haveibeenpwned.com"},{default:r(()=>[...e[11]||(e[11]=[t("https://haveibeenpwned.com",-1)])]),_:1}),e[13]||(e[13]=t(" 以查看密碼是否暴露。",-1))]),e[36]||(e[36]=l('<h4 id="本地備份" tabindex="-1">本地備份 <a class="header-anchor" href="#本地備份" aria-label="Permalink to “本地備份”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-backup.png" alt=""></p><p>無論密碼文件存儲在何處，你都應該在計算機上保留一份本地備份。幸運的是，KeeWeb 內置了這個功能。你可以備份到特定路徑，並將其設置為定期備份，或者只在文件更改時進行備份。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我實際使用 KeeWeb 已經好幾年了，它完全改變了我存儲密碼的方式。雲同步是我長期使用 KeeWeb 的主要功能，這樣我不必擔心在多個設備上保存多個不同步的文件。如果你想要一個具有云同步功能的密碼管理工具，KeeWeb 就是你應該關注的東西。</p><hr>',6)),a("p",null,[e[15]||(e[15]=t("via: ",-1)),n(s,{href:"https://www.ostechnix.com/keeweb-an-open-source-cross-platform-password-manager/"},{default:r(()=>[...e[14]||(e[14]=[t("https://www.ostechnix.com/keeweb-an-open-source-cross-platform-password-manager/",-1)])]),_:1})]),a("p",null,[e[20]||(e[20]=t("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/editor/"},{default:r(()=>[...e[16]||(e[16]=[t("EDITOR",-1)])]),_:1}),e[21]||(e[21]=t(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[17]||(e[17]=[t("lujun9972",-1)])]),_:1}),e[22]||(e[22]=t(" 譯者：",-1)),n(s,{href:"https://github.com/jlztan"},{default:r(()=>[...e[18]||(e[18]=[t("jlztan",-1)])]),_:1}),e[23]||(e[23]=t(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:r(()=>[...e[19]||(e[19]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[26]||(e[26]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[24]||(e[24]=[t("LCTT",-1)])]),_:1}),e[27]||(e[27]=t(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:r(()=>[...e[25]||(e[25]=[t("Linux中國",-1)])]),_:1}),e[28]||(e[28]=t(" 榮譽推出",-1))])])}const x=o(d,[["render",u]]);export{W as __pageData,x as default};
